def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    result = round(v1 / v2, 3)

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "calculation": "v1 / v2",
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
